UPDATE public.profiles SET tenant_id=t,role_id=r,role_key='pfleger',is_active=true,status='active',display_name='CP365 Test' WHERE id=u;
INSERT INTO auth.sessions(id,user_id,not_after) VALUES(s,u,clock_timestamp()+interval '1 hour');
INSERT INTO public.clients(id,tenant_id,first_name,last_name,status) VALUES(c,t,'CP365','Test','aktiv');
INSERT INTO public.client_module_assignments(tenant_id,client_id,module_key,status,is_active) VALUES(t,c,'pflege','active',true);
INSERT INTO public.medications(id,tenant_id,client_id,name,status,is_prn,active_ingredient,strength,form,prescribed_dose,dose_unit,route,prescribed_by,start_date,indication) VALUES(tr,t,c,'Metamizol','active',false,'Metamizol-Natrium','500 mg','Tablette','1','Tablette','oral','Ärztliche Verordnung','2026-10-01','Dokumentierte Schmerzindikation');
PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','session_id',s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint)::text,true);

p:=$packet${"schemaVersion": "1", "action": "create", "requestId": "00000000-0000-4000-8000-000000000030", "tenantId": "00000000-0000-4000-8000-000000000020", "clientId": "00000000-0000-4000-8000-000000000002", "medicationId": "00000000-0000-4000-8000-000000000001", "actorId": "00000000-0000-4000-8000-000000000012", "expectedHeadId": null, "expectedRevision": 0, "entry": {"kind": "reconciliation", "title": "Vollständiger Vorgang reconciliation", "plannedAt": "2026-10-15T12:13:14.123456Z", "occurredAt": null, "medicationId": "00000000-0000-4000-8000-000000000001", "clientId": "00000000-0000-4000-8000-000000000002", "orderVersion": "2026-10-15T12:13:14.123456Z", "sourceReview": {"planFingerprint": "sha256:1111111111111111111111111111111111111111111111111111111111111111", "documentIds": ["00000000-0000-4000-8000-000000000003"], "discrepancies": [], "allergyState": "documented", "allergyText": "Latex dokumentiert", "clarification": "", "decision": "confirmed"}, "order": {"medicationName": "Metamizol", "activeIngredient": "Metamizol-Natrium", "strength": "500 mg", "form": "Tablette", "dose": "1", "unit": "Tablette", "route": "oral", "prescriber": "Ärztliche Verordnung", "validFrom": "2026-10-01", "validUntil": null, "indication": "Dokumentierte Schmerzindikation", "isPrn": false, "minimumIntervalMinutes": null, "maximumDose": null, "maximumDoseUnit": "", "maximumPeriodHours": null}, "schedule": {"versionId": null, "effectiveFrom": null, "slots": [], "changeReason": ""}, "administration": {"outcome": "planned", "actualAt": null, "actualDose": null, "unit": "", "route": "", "performedBy": null, "deviationReason": "", "prnIndication": "", "precedingAdministrationIds": [], "intervalMinutes": null, "maximumPeriodDose": null}, "effect": {"administrationId": null, "observedAt": null, "observation": "", "action": "", "painScore": null}, "safety": {"state": "not_observed", "observation": "", "suspectedRelation": "", "reaction": "", "clinicianContact": "", "followUp": ""}, "witnes