ersion": "2026-10-15"}], "administrations": [{"id": "00000000-0000-4000-8000-000000000004", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:4444444444444444444444444444444444444444444444444444444444444444", "status": "administered", "occurredAt": "2026-10-15T09:14:15.654321Z", "dose": "1", "unit": "Tablette", "route": "oral"}], "statusEvents": [{"id": "00000000-0000-4000-8000-000000000005", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:5555555555555555555555555555555555555555555555555555555555555555", "previousStatus": "active", "nextStatus": "paused"}], "witnesses": [{"id": "00000000-0000-4000-8000-000000000006", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:6666666666666666666666666666666666666666666666666666666666666666", "profileId": "00000000-0000-4000-8000-000000000007", "active": true, "qualificationState": "current_documented"}, {"id": "00000000-0000-4000-8000-000000000012", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:7777777777777777777777777777777777777777777777777777777777777777", "profileId": "00000000-0000-4000-8000-000000000012", "active": true, "qualificationState": "registered_nurse_current"}], "stockMovements": [{"id": "00000000-0000-4000-8000-000000000008", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:8888888888888888888888888888888888888888888888888888888888888888", "packageId": "00000000-0000-4000-8000-000000000009", "operation": "receipt", "quantity": "10", "unit": "Tablette", "balanceAfter": "10"}]}}$packet$::jsonb;
p:=p||jsonb_build_object('tenantId',t,'clientId',c,'medicationId',tr,'actorId',u,'requestId',gen_random_uuid(),'sources',care_private.medication_source_snapshot(t,c,tr));
p:=jsonb_set(p,'{entry,clientId}',to_jsonb(c));p:=jsonb_set(p,'{entry,medicationId}',to_jsonb(tr));
p:=jsonb_set(p,'{entry,orderVersion}',p#>'{sources,order,updatedAt}');
p:=jsonb_set(p,'{entry,sourceReview}',jsonb_build_object('planFingerprint',p#>'{sources,order,fingerprint}','documentIds','[]'::jsonb,'discrepancies','[]'::jsonb,'allergyState',p#>'{sources,allergies,state}','allergyText',p#>'{sources,allergies,text}','clarification','','decision','confirmed'));
BEGIN PERFORM care_private.commit_medication_safety_packet(jsonb_set(p,'{entry,order,dose}','"2"'));RAISE EXCEPTION 'Forged native dose accepted';EXCEPTION WHEN check_violation THEN NULL;END;
BEGIN UPDATE public.medications SET prescribed_dose='2' WHERE id=tr;PERFORM care_private.commit_medication_safety_packet(p);RAISE EXCEPTION 'Stale native prescription accepted';EXCEPTION WHEN check_violation THEN NULL;END;
receipt:=care_private.commit_medication_safety_packet(p);replay:=care_private.commit_medication_safety_packet(p);
IF replay IS DISTINCT FROM receipt OR (SELECT count(*) FROM public.medication_safety_events WHERE tenant_id=t)<>1 OR (SELECT count(*) FROM care_private.medication_safety_requests WHERE tenant_id=t)<>1 THEN RAISE EXCEPTION 'Replay duplicated event or receipt';END IF;
v:=care_private.confirm_medication_safety_packet(t,c,tr,u,(p->>'requestId')::uuid,p);IF v IS DISTINCT FROM receipt THEN RAISE EXCEPTION 'Confirmation mismatch';END IF;
BEGIN PERFORM care_private.commit_medication_safety_packet(jsonb_set(p,'{entry,title}','"Conflicting replay title"'));RAISE EXCEPTION 'Conflicting replay accepted';EXCEPTION WHEN check_violation THEN NULL;END;
old_packet:=p||jsonb_build_object('action','revise','requestId',gen_random_uuid(),'expectedHeadId',receipt#>'{original,headId}','expectedRevision',1,'original',receipt->'original','reason','Konkrete dokumentierte Fortschreibung');old_packet:=jsonb_set(old_packet,'{entry,title}','"Erste dokumentierte Fortschreibung"');
BEGIN PERFORM care_private.commit_medication_safety_packet(jsonb_set(old_packet,'{entry,kind}','"order_capture"'));RAISE EXCEPTION 'Event kind change accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
revised:=care_private.commit_medication_safety_packet(old_packet);
IF revised#>>'{original,revision}'<>'2' OR jsonb_array_length(revised#>'{original,history}')<>2 THEN RAISE EXCEPTION 'Append history missing';END IF;
BEGIN PERFORM care_private.commit_medication_safety_packet(jsonb_set(old_packet,'{requestId}',to_jsonb(gen_random_uuid())));RAISE EXCEPTION 'Stale CAS accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
replay:=care_private.commit_medication_safety_packet(p);IF replay IS DISTINCT FROM receipt THEN RAISE EXCEPTION 'Original receipt changed after subsequent revision';END IF;
BEGIN UPDATE public.medication_safety_events SET reason='mutated' WHERE tenant_id=t;RAISE EXCEPTION 'Original modification accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
BEGIN UPDATE care_private.medication_safety_requests SET packet='{}'::jsonb WHERE tenant_id=t;RAISE EXCEPTION 'Receipt modification accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
IF (SELECT count(*) FROM pg_trigger WHERE tgname IN('medication_safety_immutable','medication_safety_receipt_immutable') AND (tgtype::integer & 8)=8 AND tgenabled='O')<>2 THEN RAISE EXCEPTION 'Removal guards absent';END IF;
IF (SELECT count(*) FROM public.medication_safety_events WHERE tenant_id=t)<>2 OR (SELECT count(*) FROM care_private.medication_safety_requests WHERE tenant_id=t)<>2 THEN RAISE EXCEPTION 'Rejected operation persisted data';END IF;
UPDATE public.profiles SET role_id=null,role_key='unassigned' WHERE id=u;
BEGIN PERFORM care_private.commit_medication_safety_packet(p);RAISE EXCEPTION 'Replay bypassed withdrawn permission';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
passed:=true;RAISE EXCEPTION USING ERRCODE='Z0001';
EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;END;
IF NOT passed OR EXISTS(SELECT 1 FROM public.tenants WHERE id=t) OR EXISTS(SELECT 1 FROM auth.users WHERE id=u) THEN RAISE EXCEPTION 'Test or cleanup failed';END IF;
END $test$;


